for tx in [-0.12, -0.10, -0.08]:
    for tz in [0.85, 0.78, 0.76]:
        tp = [tx, -0.0759, tz] + q_grasp
        pr = primitives.call(
            name="probe_robotwin2_motion_plan", arm_tag="left", evidence_handles=handles, target_pose=tp
        )
        print(f"probe ({tx}, -0.0759, {tz}):", pr.ok, pr.output.get("status") if pr.ok else pr.error)

q1 = cp1[3:]
q_top = [0.5, -0.5, 0.5, 0.5]
q_top2 = [0.7071, 0.7071, 0.0, 0.0]

for q_name, q in [("q1", q1), ("q_top", q_top), ("q_top2", q_top2)]:
    for tx in [-0.10, -0.08]:
        for tz in [0.85, 0.77]:
            tp = [tx, -0.0759, tz] + q
            pr = primitives.call(
                name="probe_robotwin2_motion_plan", arm_tag="left", evidence_handles=handles, target_pose=tp
            )
            print(f"{q_name} ({tx}, {tz}):", pr.ok, pr.output.get("status") if pr.ok else pr.error)

